    // 修改为title和子链都可以展示点击推荐
    // 1.寻找每条结果的外层div
    var $result = getResult($extQuery);

    if ($result.length == 0) {
      return;
    }

    $result.on('click', 'a', function (ev) {
      var $a = $(ev.target).closest('a');
      displayExtQuery($extQuery, $a, sugQuerys, rank, classid, extQueryIdTexts);
    });
  }

  function displayExtQuery($extQuery, $a, sugQuerys, rank, classid, extQueryIdTexts) {
    var wordNum;
    if ($extQuery.data('render')) {
      wordNum = $extQuery.data('wordNum');
    } else {
      wordNum = reBuild($extQuery, sugQuerys, rank, classid, extQueryIdTexts);
      $extQuery.data('render', 1);
      $extQuery.data('wordNum', wordNum);
    }

