      }
    });

    $('.r-sech.ad_ext_query').each(function () {
      $(this).css('display', 'none');
    });
  }

  function displayDelay($ele) {
    if (!$ele) {
      return;
    }

    // ie直接展示
    if (!!window.ActiveXObject || 'ActiveXObject' in window) {
      $ele.css('display', '');
    }
    // 需要展现当前节点（防止同时展现多个结果的推荐）
    $ele.data('needshow', '1');
    var hidden;
    var visibilityChange;

    if (typeof document.hidden !== 'undefined') {
      // Opera 12.10 and Firefox 18 and later support
      hidden = 'hidden';
      visibilityChange = 'visibilitychange';
    } else if (typeof document.msHidden !== 'undefined') {
      hidden = 'msHidden';
      visibilityChange = 'msvisibilitychange';
    } else if (typeof document.webkitHidden !== 'undefined') {
      hidden = 'webkitHidden';
      visibilityChange = 'webkitvisibilitychange';
    }

    var onVisibilityChange = function onVisibilityChange() {
      if (!document[hidden] && $ele.css('display') == 'none') {
        if ($ele.data('needshow') == '1') {
          $ele.slideToggle();
          window.HINTVIEWPORT && window.HINTVIEWPORT.showSuggReport($ele);
        }

        $(document).off(visibilityChange, onVisibilityChange);
      }
    };

    if (visibilityChange) {
      if ($ele.css('display') == 'none') {
        $(document).on(visibilityChange, onVisibilityChange);
      }
    } else {
      $ele.css('display', '');
      window.HINTVIEWPORT && window.HINTVIEWPORT.showSuggReport($ele);
    }
  }

  function dealAdExt($extQuery, sugQuerys, rank, classid, extQueryIdTexts) {
    var preAdResult = $extQuery.parent('.biz_rb');

    if (preAdResult) {
      preAdResult
        .find('h3.biz_title a')
        .first()
        .on('click', function () {
          var wordNum = reBuild($extQuery, sugQuerys, rank, classid, extQueryIdTexts);

          if (wordNum > 0) {
            clickTitleLog($extQuery, sugQuerys, rank, classid, 'ext');
          }

          displayNoneOther(rank);
        });
    }
  }

  function getResult($extQuery) {
    var $result = $extQuery.closest('.rb');

    if ($result.length == 0) {
      $result = $extQuery.closest('.vrwrap');
    }

    return $result;
  }

  function addSet(arr, item) {
    if ($.inArray(item, arr) === -1) {
      arr.push(item);
    }
  }

  // 判断url是否有效
  function validUrl(url) {
    return url && url.indexOf('javascript') !== 0 && url.indexOf('/link?') !== 0;
  }

  function getUrlInfo($link) {
    var url = $link.attr('href');

    if (url && validUrl(url)) {
      return url;
    }
  }

  function getValidInfo($doc, $extQuery) {
    if ($extQuery.data('normal')) {
      return $extQuery.data('url');
    }

    // 通用title的链接
    var urlInfo = getUrlInfo($doc.find('a.vr-title'));
    if (urlInfo) {
      return urlInfo;
    }

    var links = $doc.find('a[href]');

    for (var i = 0; i < links.length; i++) {
      urlInfo = getUrlInfo(links.eq(i));

      if (urlInfo) {
        return urlInfo;
      }
    }

    return $extQuery.data('url');
  }

  function getDocUrls($doc, limit) {
    limit = limit || 1;
    var urls = [];

    if (!$doc) {
      return urls;
    }

    $doc.find('a[href]').each(function (i, e) {
      if (urls.length >= limit) {
        return;
      }

      var $e = $(e);
      var id = $e.attr('id');

      if (id && id.indexOf('uigs_ext_') === 0) {
        // 忽略点后推链接
        return;
      }

      var href = $e.attr('href');

      if (validUrl(href)) {
        addSet(urls, href);
      }
    });
    return urls;
  }

  function getUrls($extQuery) {
    var urls = [];
    $('.ext_query').each(function (_, e) {
      if (urls.length >= ALL_URL_LIMIT) {
        return;
      }

      var $e = $(e);

      if ($e.attr('id') === $extQuery.attr('id')) {
        return;
      }

      var $doc = getResult($e);

      if (!$doc || $doc.length === 0) {
        return;
      }

      var dataUrl = $e.data('url');

      if ($e.data('normal') && dataUrl) {
        addSet(urls, dataUrl);
        return;
      }

      var docUrls = getDocUrls($doc, DOC_URL_LIMIT);

      if (docUrls && docUrls.length >= 1) {
        urls = urls.concat(docUrls);
        return;
      }

      if (dataUrl) {
        addSet(urls, dataUrl);
      }
    });
    return urls.slice(0, ALL_URL_LIMIT);
  }

  function getSuburls($doc, $extQuery) {
    if ($extQuery.data('normal')) {
      return [];
    }

    return getDocUrls($doc, DOC_URL_LIMIT);
  }

  function getDocInfo($extQuery, $result) {
    var url;

    if ($result) {
      url = getValidInfo($result, $extQuery);
    }

    var urls = getUrls($extQuery);
    var suburls = getSuburls($result, $extQuery);
    return {
      urls: urls,
      suburls: suburls,
      url: url || $extQuery.data('url') || '',
      docId: $extQuery.data('docid'),
