          trafficSign: 'web',
          from: 'ajax',
          front_screen_resolution: getScreen(),
          isWaigou: param.pidType,
          expinfo: JSON.stringify(expinfo),
        },
        docInfo,
      )),
      contentType: 'application/json',
      dataType: 'json',
    });
  }

  function asyncClickSuggHandle($extQuery, classid, rank, extQueryIdTexts) {
    var $result = getResult($extQuery);

    if ($result.length == 0) {
      return;
    }

    var promise;
    $result.on('click', 'a', function (ev) {
      if (!promise) {
        var docInfo = getDocInfo($extQuery, $result);
        promise = clickSugg(docInfo);
      }

      promise.done(function (ret) {
        var $a = $(ev.target).closest('a');

        if (ret && ret.list && ret.list.length) {
          displayExtQuery($extQuery, $a, ret.list, rank, classid, extQueryIdTexts);
        }
      });
    });
  }

  function clickSuggHandle($extQuery, classid, rank, extQueryIdTexts) {
    var extQueryAId = extQueryIdTexts[0] + '_' + extQueryIdTexts[1] + '_' + classid + '_sq_ext_a_' + rank;
    var $extA = $('#' + extQueryAId);
    var ext = $extA.text();

    if (ext == '') {
      return true;
    }

    $extA.remove();
    var sugQueryList = ext.replace(/；/g, ';').split(';');
    var sugQuerys = [];

    for (var i = 0; i < sugQueryList.length; i++) {
      if (sugQueryList[i]) {
        sugQuerys.push({
          query: sugQueryList[i],
        });
      }
    }
    // 广告的rank>10000
    if (rank >= 10000) {
      dealAdExt($extQuery, sugQuerys, rank, classid, extQueryIdTexts);
      return;
    }
    // 修改为title和子链都可以展示点击推荐
    // 1.寻找每条结果的外层div
    var $result = getResult($extQuery);

    if ($result.length == 0) {
      return;
    }

    $result.on('click', 'a', function (ev) {
      var $a = $(ev.target).closest('a');
      displayExtQuery($extQuery, $a, sugQuerys, rank, classid, extQueryIdTexts);
    });
  }

  function displayExtQuery($extQuery, $a, sugQuerys, rank, classid, extQueryIdTexts) {
    var wordNum;
    if ($extQuery.data('render')) {
      wordNum = $extQuery.data('wordNum');
    } else {
      wordNum = reBuild($extQuery, sugQuerys, rank, classid, extQueryIdTexts);
      $extQuery.data('render', 1);
      $extQuery.data('wordNum', wordNum);
    }

    if (/javascript:\s*void\s*\(\s*0\s*\)/.test($a.attr('href'))) {
      return;
    }

    if (wordNum > 0) {
      clickTitleLog($extQuery, sugQuerys, rank, classid, 'ext');
    }

    displayNoneOther(rank);
  }

  function extQueryInit() {
    // 初始化
    $('.ext_query').each(function () {
      var $extQuery = $(this);

      // 跳过已经初始化的元素
      if ($extQuery.attr('init') === '1') {
        return;
      }

      var extQueryIdText = $extQuery.attr('id');
      var extQueryIdTexts = extQueryIdText.split('_');
      var extQueryIdTextsLength = extQueryIdTexts.length;

      if (extQueryIdTextsLength < 2) {
        return;
      }

      var classid = extQueryIdTexts[2];
      var rank = extQueryIdTexts[extQueryIdTextsLength - 1];
      var async = $extQuery.data('async');

      if (async) {
        asyncClickSuggHandle($extQuery, classid, rank, extQueryIdTexts);
      } else {
        clickSuggHandle($extQuery, classid, rank, extQueryIdTexts);
      }

      // 标记为已初始化
      $extQuery.attr('init', '1');
    });
  }
  window.extQueryInit = extQueryInit;
  extQueryInit();
});
